function apply(lang){const copy=COPY[lang]||COPY.en;document.documentElement.lang=lang;document.documentElement.dataset.language=lang;document.title=lang==='ja'?'LLMs モニター — 残量を、ひと目で。':'LLMs Monitor — Know what remains';for(const node of document.querySelectorAll('[data-copy]')){const value=copy[node.dataset.copy];if(value!==undefined)node.innerHTML=value}for(const button of document.querySelectorAll('[data-lang]'))button.setAttribute('aria-pressed',String(button.dataset.lang===lang));try{localStorage.setItem('llms-product-language',lang)}catch{}}
for(const button of document.querySelectorAll('[data-lang]'))button.addEventListener('click',()=>apply(button.dataset.lang));let initial='en';try{initial=localStorage.getItem('llms-product-language')||(/^ja/i.test(navigator.language)?'ja':'en')}catch{}apply(initial);
